package com.logatron.auth.application;
import com.logatron.auth.domain.PlatformRole;import com.logatron.auth.persistence.*;import com.logatron.catalog.domain.CatalogEnums.*;import com.logatron.catalog.persistence.*;import com.logatron.common.error.ApiException;import org.junit.jupiter.api.*;import org.mockito.Mockito;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class AuthorizationServiceTest{
 private final UserAccountRepository users=mock(UserAccountRepository.class);private final ProjectMembershipRepository memberships=mock(ProjectMembershipRepository.class);private final EnvironmentGrantRepository grants=mock(EnvironmentGrantRepository.class);private final ProjectRepository projects=mock(ProjectRepository.class);private final EnvironmentRepository environments=mock(EnvironmentRepository.class);private final AuthorizationService service=new AuthorizationService(users,memberships,grants,projects,environments);
 @Test void developerReceivesOnlyExplicitEnvironmentGrants(){UUID userId=UUID.randomUUID(),projectId=UUID.randomUUID(),devId=UUID.randomUUID(),prodId=UUID.randomUUID(),membershipId=UUID.randomUUID();var user=mock(UserAccountEntity.class);when(user.getId()).thenReturn(userId);var project=mock(ProjectEntity.class);when(project.getId()).thenReturn(projectId);var role=mock(RoleEntity.class);when(role.getCode()).thenReturn(PlatformRole.DEVELOPER);var membership=mock(ProjectMembershipEntity.class);when(membership.getId()).thenReturn(membershipId);when(membership.getProject()).thenReturn(project);when(membership.getRole()).thenReturn(role);var dev=mock(EnvironmentEntity.class);when(dev.getId()).thenReturn(devId);var grant=mock(EnvironmentGrantEntity.class);when(grant.getMembership()).thenReturn(membership);when(grant.getEnvironment()).thenReturn(dev);when(memberships.findActiveDetailedForUser(eq(userId),any(Instant.class))).thenReturn(List.of(membership));when(grants.findDetailedByMembershipIds(List.of(membershipId))).thenReturn(List.of(grant));var scope=service.resolveScope(new AuthenticatedUser(userId,"i","s","u","User",null));assertThat(scope.projects().get(projectId).environmentIds()).containsExactly(devId);assertThatThrownBy(()->service.require(scope,RequestedResourceScope.environment(projectId,prodId))).isInstanceOf(ApiException.class);}
 @Test void projectAdminReceivesAllProjectEnvironmentsButNotAnotherProject(){UUID userId=UUID.randomUUID(),projectId=UUID.randomUUID(),other=UUID.randomUUID(),envId=UUID.randomUUID();var project=mock(ProjectEntity.class);when(project.getId()).thenReturn(projectId);var role=mock(RoleEntity.class);when(role.getCode()).thenReturn(PlatformRole.PROJECT_ADMIN);var membership=mock(ProjectMembershipEntity.class);when(membership.getId()).thenReturn(UUID.randomUUID());when(membership.getProject()).thenReturn(project);when(membership.getRole()).thenReturn(role);var env=mock(EnvironmentEntity.class);when(env.getId()).thenReturn(envId);when(memberships.findActiveDetailedForUser(eq(userId),any())).thenReturn(List.of(membership));when(environments.findByProjectIdOrderByCode(projectId)).thenReturn(List.of(env));var scope=service.resolveScope(new AuthenticatedUser(userId,"i","s","u","User",null));assertThatCode(()->service.requireAdministration(scope,projectId)).doesNotThrowAnyException();assertThatThrownBy(()->service.requireAdministration(scope,other)).isInstanceOf(ApiException.class);}
 @Test void globalAdminReceivesAllProjects(){UUID userId=UUID.randomUUID(),projectId=UUID.randomUUID(),envId=UUID.randomUUID();var project=mock(ProjectEntity.class);when(project.getId()).thenReturn(projectId);var role=mock(RoleEntity.class);when(role.getCode()).thenReturn(PlatformRole.ADMIN);var membership=mock(ProjectMembershipEntity.class);when(membership.getRole()).thenReturn(role);var env=mock(EnvironmentEntity.class);when(env.getId()).thenReturn(envId);when(memberships.findActiveDetailedForUser(eq(userId),any())).thenReturn(List.of(membership));when(projects.findAll()).thenReturn(List.of(project));when(environments.findByProjectIdOrderByCode(projectId)).thenReturn(List.of(env));var scope=service.resolveScope(new AuthenticatedUser(userId,"i","s","u","User",null));assertThat(scope.globalAdmin()).isTrue();assertThat(scope.projects()).containsKey(projectId);}
}
